import org.jsoup.Connection;
import org.jsoup.helper.UrlBuilder;
import org.jsoup.internal.StringUtil;
import org.junit.Before;
import org.junit.Test;
import org.junit.runner.RunWith;
import org.mockito.Mock;
import org.mockito.Mockito;
import org.mockito.junit.MockitoJUnitRunner;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertThrows;
import static org.mockito.ArgumentMatchers.anyString;
import static org.mockito.Mockito.when;

@RunWith(MockitoJUnitRunner.class)
public class UrlBuilderTest {

    @Mock
    private Connection connection;

    @Before
    public void setup() {
        // No setup needed for this test class
    }

    @Test
    public void newUrlBuilder_isNotNull() {
        UrlBuilder urlBuilder = new UrlBuilder(null);
        assert urlBuilder != null;
    }

    @Test
    public void buildUrl_withInputUrl_returnsCorrectUri() throws MalformedURLException, URISyntaxException {
        URL inputUrl = new URL("http://example.com");
        UrlBuilder urlBuilder = new UrlBuilder(inputUrl);

        when(connection.toString()).thenReturn("/path/to/resource");

        URI uri = urlBuilder.build().toURI();
        assertEquals("http://example.com/path/to/resource", uri.toString());
    }

    @Test
    public void buildUrl_withInputUrl_andAppendedKeyVal_returnsCorrectUri() throws MalformedURLException, URISyntaxException {
        URL inputUrl = new URL("http://example.com");
        UrlBuilder urlBuilder = new UrlBuilder(inputUrl);

        Connection.KeyVal kv = new Connection.KeyVal( "key", "value" );
        urlBuilder.appendKeyVal(kv);

        URI uri = urlBuilder.build().toURI();
        assertEquals("http://example.com/path/to/resource?key=value", uri.toString());
    }

    @Test
    public void appendKeyVal_withValidKeyVal_addsCorrectKeyAndValue() throws UnsupportedEncodingException {
        UrlBuilder urlBuilder = new UrlBuilder(null);

        Connection.KeyVal kv = new Connection.KeyVal( "key", "value" );
        urlBuilder.appendKeyVal(kv);

        String query = urlBuilder.build().getQuery();
        assertEquals("key=value", query);
    }

    @Test
    public void appendKeyVal_withInvalidEncoding_throwsUnsupportedEncodingException() {
        UrlBuilder urlBuilder = new UrlBuilder(null);

        assertThrows(UnsupportedEncodingException.class, () -> urlBuilder.appendKeyVal(new Connection.KeyVal( "key", "value with invalid encoding" )));
    }
}
